/**
 * Parses a string containing integers separated by commas and/or spaces,
 * and returns a vector of integers. The function is robust against irregular
 * spacing and inclusion of non-numeric characters.
 *
 * @param input_string A string containing the numbers to be parsed, separated by commas or spaces.
 * @return A vector containing the parsed integers.
 *
 * Example:
 * auto result = parse_integer_list("1, 2, 3");
 * // result should be {1, 2, 3}
 *
 * auto result = parse_integer_list("4,5 6, 7");
 * // result should be {4, 5, 6, 7}
 *
 * auto result = parse_integer_list("8,9,10");
 * // result should be {8, 9, 10}
 *
 * auto result = parse_integer_list("11, 12,abc,13");
 * // result should be {11, 12, 13}
 */
std::vector<int> parse_integer_list(const std::string& input_string) {
    std::vector<int> integers;
    std::stringstream ss(input_string);
    std::string token;

    while (getline(ss, token, ',')) {
        std::stringstream token_stream(token);
        int number;
        while (token_stream >> number) {
            integers.push_back(number);
        }
        // Check if there was any leftover after the last comma
        if (token_stream.fail() && !token.empty()) {
            std::cerr << "Warning: Invalid integer value found - " << token << std::endl;
        }
    }

    return integers;
}

// Function to check the correctness of the parse_integer_list function
void check_function() {
    assert((parse_integer_list("1, 2, 3") == std::vector<int>{1, 2, 3}));
    assert((parse_integer_list("4,5 6, 7") == std::vector<int>{4, 5, 6, 7}));
    assert((parse_integer_list("8,9,10") == std::vector<int>{8, 9, 10}));
    assert((parse_integer_list("11, 12,abc,13") == std::vector<int>{11, 12, 13}));
    std::cout << "All test cases passed!" << std::endl;
}

// Main function
int main() {
    check_function();
    return 0;
}

