```java
class Solution {
    public int[] maxSlidingWindow(int[] nums, int m, int k) {
        if(nums.length==0||m==0||k==0) return new int[]{};
        int len=nums.length;
        int[] result=new int[(len-m+1)];
        int index=0;
        Deque<Integer> deque=new LinkedList<>();
        for(int i=0;i<len;i++){
            if(!deque.isEmpty()&&deque.peek()<i-m+1){
                deque.poll();
            }
            while(!deque.isEmpty()&&nums[i]>=nums[deque.peekLast()]){
                deque.pollLast();
            }
            deque.offer(i);
            if(i>=m-1){
                result[index++]=Math.max(nums[deque.peek()],result[index-1]);
            }
        }
        return result;
    }
}
