function printSudokuGrid(grid) {
	for (let i = 0; i < grid.length; i++) {
		if (i % 3 === 0 && i !== 0) {
			console.log("- - - + - - + - -");
		}
		for (let j = 0; j < grid[i].length; j++) {
			if (j % 3 === 0 && j !== 0) {
				process.stdout.write(" | ");
			}
			process.stdout.write(`${grid[i][j] || ' '}    `);
		}
		process.stdout.write("\n");
	}
}

