// Importing the necessary package for memoization
import { memoize } from 'lodash';

/**
 * Calculate the nth Fibonacci number using memoization to optimize performance.
 * 
 * The Fibonacci sequence is a series of numbers where each number is the sum
 * of the two preceding ones, usually starting with 0 and 1. That is:
 * F(0) = 0, F(1) = 1, and F(n) = F(n-1) + F(n-2) for n > 1.
 * 
 * This function uses memoization to cache the results of previous calculations,
 * significantly improving the efficiency for large values of n.
 * 
 * @param n The position in the Fibonacci sequence (must be a non-negative integer).
 * @returns The nth Fibonacci number.
 * 
 * Example usage:
 * console.log(calculateFibonacci(10)); // Output: 55
 * console.log(calculateFibonacci(0));  // Output: 0
 * console.log(calculateFibonacci(1));  // Output: 1
 */
const calculateFibonacci = memoize((n: number): number => {
    if (n < 0) {
        throw new Error("Input must be a non-negative integer");
    }
    if (n === 0) {
        return 0;
    } else if (n === 1) {
        return 1;
    } else {
        return calculateFibonacci(n - 1) + calculateFibonacci(n - 2);
    }
});

// Main function to test the generated function
function main() {
    // Unit tests
    console.log(calculateFibonacci(10)); // Expected output: 55
    console.log(calculateFibonacci(0));  // Expected output: 0
    console.log(calculateFibonacci(1));  // Expected output: 1
    console.log(calculateFibonacci(20)); // Expected output: 6765
}

