    var AssetsLoader = function (url, callback) {
        this.url = url;
        this.callback = callback;
        this.loading = false;
    };

    AssetsLoader.prototype.start = function () {
        if (this.loading) return;
        this.loading = true;

        ajax.request(this.url).then(function (response) {
            var dom = QWeb.render('EditorAssets', {response: response});
            $(dom).appendTo(document.body);
            this.callback();
            this.loading = false;
        }.bind(this));
