        var self = this;
        this.loaders.forEach(function (loader) {
            loader.start();
        });
        this.loaders = urls.map(function (url) {
            return new AssetsLoader(url, function () {
                self.loaders = self.loaders.filter(function (l) {
                    return l !== loader;
                });
                if (!self.loaders.length) {
                    callback();
                }
            });
        });
        return this;
    };

