pe::Status PmemBuffer::Resize(size_t size) {
  if (size_ == size)
    return pe::OkStatus();

  void* new_data;
  if (size > size_)
    new_data = malloc(size);
  else
    new_data = static_cast<uint8_t*>(memalign(kAlign, size));
  if (!new_data)
    return pe::OutOfMemoryError("pmem buffer resize");

  if (size_ > 0) {
    memcpy(new_data, data_, size_);
    free(data_);
  }

  size_ = size;
  data_ = reinterpret_cast<uint8_t*>(new_data);
  return pe::OkStatus();
}

