#include <cmath>

void findPrimesUpToN(int n) {
    std::vector<bool> isPrime(n+1, true);
    isPrime[0] = isPrime[1] = false; // 0 and 1 are not prime numbers

    for (int p = 2; p <= std::sqrt(n); p++) {
