etcd::Result etcd::Client::Put(const std::string &key, const std::string &value)
{
    std::string req;
    std::string resp;
    std::string path = "/v3/keys/" + key + "?prev_value=true";
    req += "PUT " + path + "\r\n";
    req += "Content-Length: " + std::to_string(value.size()) + "\r\n";
    req += "Content-Type: application/x-protobuf\r\n";
    req += "\r\n";
    req += value;

    int ret = send(_sockfd, req.c_str(), req.size(), 0);
    if (ret < 0) {
        perror("send");
        return Result(ErrCode::kSendFailed, "send failed");
    }

    ret = recv(_sockfd, resp.data(), resp.capacity(), 0);
    if (ret <= 0) {
        perror("recv");
        return Result(ErrCode::kRecvFailed, "recv failed");
    }

    return ParseResp(resp);
}

