function maxProductOfThree(nums) {
    // Sort the array in ascending order
    nums.sort((a, b) => a - b);

    // The maximum product can be either:
    // 1. Product of the three largest numbers
    // 2. Product of the two smallest numbers (which could be negative) and the largest number
    const n = nums.length;
    return Math.max(
        nums[n - 1] * nums[n - 2] * nums[n - 3], // Case 1: Product of three largest numbers
        nums[0] * nums[1] * nums[n - 1] // Case 2: Product of two smallest and one largest number
    );
}

// Check function to verify the correctness of the solution
function check() {
    console.assert(maxProductOfThree([-10, -10, 5, 2]) === 500, 'Test case 1 failed');
    console.assert(maxProductOfThree([1, 2, 3]) === 6, 'Test case 2 failed');
    console.assert(maxProductOfThree([1, 2, 3, 4]) === 24, 'Test case 3 failed');
    console.assert(maxProductOfThree([-5, -4, -3, -2]) === -20, 'Test case 4 failed');
    console.log('All test cases passed!');
}

