    private static boolean check(int mid, List<Integer> list) {
        int cnt = 0;
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i) >= mid) {
                cnt += (list.get(i) - mid + 1);
            }
        }
        return cnt <= m;
