    /**
     * Checks if a given list of integers contains only one unique pair of numbers that are symmetrically equal.
     *
     * A symmetric pair means two numbers that are equal but appear at different positions in the list,
     * effectively being equidistant from the center of the list. The function returns true if there
     * is exactly one such pair, and false if there are none or more than one.
     *
     * @param numbers The list of integers to check for a single symmetric pair.
     * @return true if there is exactly one symmetric pair, false otherwise.
     */
    public static boolean hasSingleSymmetricPair(List<Integer> numbers) {
        Set<Integer> seen = new HashSet<>();
        int middleIndex = numbers.size() / 2;
        int count = 0;

        for (int i = 0; i < numbers.size(); i++) {
            int complement = numbers.get(numbers.size() - 1 - i);
            if (seen.contains(complement)) {
                count++;
            } else {
                seen.add(numbers.get(i));
            }

            // Check if we've found the second element of the potential symmetric pair
            if (i == middleIndex && count > 1) {
                return false;
            }
        }

        // Check if there's exactly one symmetric pair
        return count == 1;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(hasSingleSymmetricPair(List.of(1, 3, 2, 3, 1))); // false
        System.out.println(hasSingleSymmetricPair(List.of(2, 1, 3, 1, 2))); // true
        System.out.println(hasSingleSymmetricPair(List.of(4, 5, 6)));       // true
        System.out.println(hasSingleSymmetricPair(List.of(7, 8, 9, 8, 7))); // false
    }
}

