 /**
  * Calculate the Euclidean distance between two points in n-dimensional space.
  *
  * The Euclidean distance between points p and q is the length of the line segment connecting them.
  * In Cartesian coordinates, if p = (p1, p2,..., pn) and q = (q1, q2,..., qn) then the distance
  * (d) between p and q is given by the Pythagorean formula:
  *
  *     d(p, q) = sqrt((q1 - p1)^2 + (q2 - p2)^2 + ... + (qn - pn)^2)
  *
  * @param Vector $point1 The first point as a vector.
  * @param Vector $point2 The second point as a vector.
  * @return float The Euclidean distance between the two points.
  */
 function calculateEuclideanDistance(Vector $point1, Vector $point2): float {
     $sumOfSquares = 0;
     for ($i = 0; $i < $point1->getSize(); $i++) {
         $difference = $point1->get($i) - $point2->get($i);
         $sumOfSquares += $difference ** 2;
     }
     return sqrt($sumOfSquares);
 }

 // Check function to verify the correctness of the generated function
 function checkEuclideanDistance() {
     $pointA = new Vector([1, 2]);
     $pointB = new Vector([4, 6]);
     $distance = calculateEuclideanDistance($pointA, $pointB);
     assert(abs($distance - 5.0) < 0.001, "The calculated distance is not correct.");

     $pointC = new Vector([0, 0, 3]);
     $pointD = new Vector([5, 12, 0]);
     $distanceCD = calculateEuclideanDistance($pointC, $pointD);
     assert(abs($distanceCD - 13.0) < 0.001, "The calculated distance is not correct.");
 }

 // Run the check function to verify the results
 checkEuclideanDistance();
