import java.util.Arrays;

public class MaxSubarraySumFinder {

    /**
     * Find the maximum sum of a contiguous subarray within a one-dimensional array of numbers.
     *
     * This method implements Kadane's algorithm to find the subarray with the maximum sum in
     * linear time. If the array contains all non-positive numbers, it will return the maximum of those.
     *
     * @param nums An array of integers.
     * @return The largest sum of any contiguous subarray within the input array.
     */
    public static int findMaxSubarraySum(int[] nums) {
        if (nums == null || nums.length == 0) { // Handle empty or null array case
            return 0;
        }

        int currentSum = nums[0];
        int maxSum = nums[0];

        for (int i = 1; i < nums.length; i++) {
            currentSum = Math.max(nums[i], currentSum + nums[i]);
            maxSum = Math.max(maxSum, currentSum);
        }

        return maxSum;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(findMaxSubarraySum(new int[]{34, -50, 42, 14, -5, 86})); // Expected output: 137
        System.out.println(findMaxSubarraySum(new int[]{-2, -3, -1, -4})); // Expected output: -1
        System.out.println(findMaxSubarraySum(new int[]{1, 2, 3, 4, 5})); // Expected output: 15
        System.out.println(findMaxSubarraySum(new int[]{})); // Expected output: 0
        System.out.println(findMaxSubarraySum(null)); // Expected output: 0
    }
}

