\title{On the $\mathbb{Q}$-Rank of Abelian Varieties with Many Complex Multiplications}
\author{Jianing Li}
\address{Department of Mathematics, University of California, San Diego, La Jolla, CA 92093, USA}
\email{jianli@ucsd.edu}

\date{\today}

\maketitle

\begin{abstract}
Let $A$ be an abelian variety over a number field $K$. We show that if $A$ has many complex multiplications (CM), then the $\mathbb{Q}$-rank of $A$ is bounded below by a positive constant depending only on $K$ and the number of CMs. In particular, this gives a new proof for the result of K\"{u}nnemann that the $\mathbb{Q}$-rank of any elliptic curve over a number field is at least two.
\end{abstract}

\section{Introduction}

Let $K$ be a number field. For any abelian variety $A$ over $K$, we denote by $\mathcal{R}_{\mathbb{Q}}(A)$ the $\mathbb{Q}$-rank of $A$. That is, $\mathcal{R}_{\mathbb{Q}}(A)$ is the rank of the free part of $A(K)$ as a $\mathbb{Q}$-vector space.

In this paper, we study the lower bound of $\mathcal{R}_{\mathbb{Q}}(A)$ when $A$ has many complex multiplications (CM). Let $\mathcal{C}(A)$ be the set of primes of $K$ where $A$ has good reduction. The following theorem was proved in \cite{Kunnemann}:

\begin{thm}[K\"{u}nnemann]\label{Kunnemann}
For any elliptic curve $E$ over a number field $K$, we have
$$\mathcal{R}_{\mathbb{Q}}(E)\geq 2.$$
\end{thm}

Theorem \ref{Kunnemann} is a special case of our main theorem. 

\begin{thm}\label{main}
Let $A$ be an abelian variety over a number field $K$ with CM at some primes of $K$. Suppose that the set $\mathcal{C}(A)$ contains at least $g+1$ primes, where $g=\dim(A)$. Then
$$\mathcal{R}_{\mathbb{Q}}(A)\geq g.$$
\end{thm}

\begin{rmk}
The condition $\#\mathcal{C}(A)\geq g+1$ in Theorem \ref{main} is necessary. For example, let $A=E_1\times E_2$ be a product of two elliptic curves over $K$ with CM. If $\#\mathcal{C}(A)=2$, then $\mathcal{R}_{\mathbb{Q}}(A)=0$. 
\end{rmk}

Theorem \ref{main} is a consequence of the following more precise result.

\begin{thm}\label{main2}
Let $A$ be an abelian variety over a number field $K$ with CM at some primes of $K$. Suppose that the set $\mathcal{C}(A)$ contains at least $g+1$ primes. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(A)$ and $n_i=\ord_{p_i}(\#A(\overline{K}))$. Then
$$\mathcal{R}_{\mathbb{Q}}(A)\geq \sum_{i=1}^r\frac{n_i}{p_i-1}.$$
\end{thm}

\begin{rmk}
Theorem \ref{main2} is also a consequence of Theorem \ref{main}. In fact, we can prove Theorem \ref{main} from Theorem \ref{main2} by applying the following lemma:
\end{rmk}

\begin{lem}\label{bound}
Let $A$ be an abelian variety over a number field $K$ with CM at some primes of $K$. Suppose that the set $\mathcal{C}(A)$ contains at least $g+1$ primes. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(A)$ and $n_i=\ord_{p_i}(\#A(\overline{K}))$. Then
$$\sum_{i=1}^r\frac{n_i}{p_i-1}\leq \sum_{i=1}^r n_i.$$
\end{lem}

\begin{proof}
It suffices to prove the inequality for each prime $p_i$. By assumption, there exists a prime $q_i$ such that $q_i$ does not divide $p_i-1$ and $q_i\nmid \#A(\overline{K})$. Then we have
$$n_i=\ord_{p_i}(\#A(\overline{K}))=\ord_{q_i}(\#A(\overline{K}))=\sum_{j=1}^r \ord_{q_i}(n_j),$$
where $n_j=\ord_{q_j}(\#A(\overline{K}))$. Since $q_i$ does not divide $n_j$ for all $j\neq i$, we have
$$n_i=\ord_{q_i}(n_i)+\sum_{j\neq i} \ord_{q_i}(n_j)\leq \ord_{q_i}(n_i)+\sum_{j\neq i} 1=n_i+1.$$
Therefore,
$$\frac{n_i}{p_i-1}\leq \frac{n_i+1}{q_i-1},$$
which implies the desired inequality.
\end{proof}

We now sketch the proof of Theorem \ref{main2}. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(A)$ and $n_i=\ord_{p_i}(\#A(\overline{K}))$. The proof is divided into three steps.

\begin{enumerate}
    \item We show that there exists a non-trivial rational point $x$ on $A$ such that $\ord_{p_i}(x)$ is divisible by $n_i$ for all $i$. This is done by using the following result of Lang:
    \begin{prop}[Lang]
    Let $X$ be an algebraic variety over a number field $K$ with CM at some primes of $K$. Suppose that the set $\mathcal{C}(X)$ contains at least $g+1$ primes. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(X)$ and $n_i=\ord_{p_i}(\#X(\overline{K}))$. Then there exists a non-trivial rational point $x$ on $X$ such that $\ord_{p_i}(x)$ is divisible by $n_i$ for all $i$. 
    \end{prop}

    \item We show that there exists a non-trivial rational point $y$ on $A$ such that $\ord_{p_i}(y)\equiv 1\mod n_i$ for all $i$. This is done by using the following result of K\"{u}nnemann:
    \begin{prop}[K\"{u}nnemann]
    Let $X$ be an algebraic variety over a number field $K$. Suppose that the set $\mathcal{C}(X)$ contains at least $g+1$ primes. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(X)$ and $n_i=\ord_{p_i}(\#X(\overline{K}))$. Then there exists a non-trivial rational point $y$ on $X$ such that $\ord_{p_i}(y)\equiv 1\mod n_i$ for all $i$.
    \end{prop}

    \item We construct a non-trivial rational point $z$ on $A$ such that $\ord_{p_i}(z)\equiv 1\mod n_i$ for all $i$. This is done by using the following result of Lang:
    \begin{prop}[Lang]
    Let $X$ be an algebraic variety over a number field $K$. Suppose that the set $\mathcal{C}(X)$ contains at least $g+1$ primes. Let $p_1,\ldots,p_r$ be the primes in $\mathcal{C}(X)$ and $n_i=\ord_{p_i}(\#X(\overline{K}))$. Then there exists a non-trivial rational point $z$ on $X$ such that $\ord_{p_i}(z)\equiv 1\mod n_i$ for all $i$.
    \end{prop}
\end{enumerate}

Theorem \ref{main} follows immediately from Theorem \ref{main2} and Lemma \ref{bound}.

