class Solution {
    public int numSquares(int n) {
        // 动态规划
        // dp[i]表示i的最少平方数为dp[i]
        // dp[i] = Math.min(dp[i], Math.min(dp[i-j*j]+1, dp[j*j])) (0<j*j<=i)
        // 初始化：dp[0] = 0，dp[1] = 1
        // 结果：dp[n]

        int[] dp = new int[n+1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        dp[1] = 1;

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j * j <= i; ++j) {
                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            }
        }

        return dp[n];
    }
}
