class Solution {
    int[][] memo;

    public int numSquares(int n) {
        // 初始化记忆化搜索的缓存数组
        memo = new int[n+1][n+1];
        for (int i = 0; i <= n; ++i) {
            Arrays.fill(memo[i], -1);
        }

        return dfs(n);
    }

    private int dfs(int n) {
        if (n == 0) {
            return 0;
        }

        if (memo[n][n] != -1) {
            return memo[n][n];
        }

        int min = Integer.MAX_VALUE;
        for (int i = 1; i * i <= n; ++i) {
            min = Math.min(min, dfs(n - i * i) + 1);
        }

        memo[n][n] = min;
        return min;
    }
}
