class Solution {
    public int numSquares(int n) {
        // 暴力枚举
        // 因为平方数的范围是 [1,n]，所以枚举的范围是从1到n
        int res = Integer.MAX_VALUE;
        for (int i = 1; i * i <= n; ++i) {
            int num = i * i;
            if (num == n) {
                res = 1;
                break;
            }
            int tmp = numSquares(n - num);
            if (tmp != -1) {
                res = Math.min(res, tmp + 1);
            } else {
                break;
            }
        }

        return res;
    }
}
