class Solution {
    public int numSquares(int n) {
        // 深度优先搜索
        // 因为每个数可以被分解成一个或多个平方数之和，所以我们可以从 n 开始尝试将它分解成更小的平方数。
        // 如果找到一种方式使得所有平方数加起来等于 n，那么就找到了最小数量的平方数。

        int res = Integer.MAX_VALUE;
        dfs(0, n, 1, res);

        return res == Integer.MAX_VALUE ? 0 : res;
    }

    private void dfs(int sum, int target, int index, int[] res) {
        if (target == 0) {
            res[0] = Math.min(res[0], index);
            return;
        }

        for (int i = index; i * i <= target; ++i) {
            dfs(sum + i * i, target - i * i, i, res);
        }
    }
}
