class Solution {
    public int numSquares(int n) {
        // 数学归纳法
        // 根据数学归纳法，如果 n 是完全平方数，则需要 1 个平方数。
        // 如果 n 可以表示为两个不同的平方数之和，则需要 2 个平方数。
        // 如果 n 可以表示为三个不同的平方数之和，则需要 3 个平方数。
        // 这种情况一直持续到 n 可以表示为 n 个平方数之和。

        // 特殊情况处理：当 n 是完全平方数时，只需要 1 个平方数
        if ((int)Math.sqrt(n) * (int)Math.sqrt(n) == n) {
            return 1;
        }

        // 如果 n 可以被 4 整除，那么它可以表示为 4 的倍数个平方数之和
        while (n % 4 == 0) {
            n /= 4;
        }

        // 如果 n 形式为 8k + 7，那么 n 需要至少 7 个平方数之和
        if (n % 8 == 7) {
            return 4;
        }

        // 对于其他情况，使用数学归纳法来确定最少的平方数数量
        for (int i = 1; i * i <= n; ++i) {
            int remainder = n - i * i;
            if (isPerfectSquare(remainder)) {
                return 2;
            }
        }

        return 3;
    }

    private boolean isPerfectSquare(int n) {
        int sqrt = (int)Math.sqrt(n);
        return sqrt * sqrt == n;
    }
}
