    @Override
    public void actionPerformed(ActionEvent e) {
        Object source = e.getSource();
        if (source instanceof JButton) {
            JButton button = (JButton) source;
            String buttonText = button.getText();
            if ("=".equals(buttonText)) {
                try {
                    double result = evaluateExpression();
                    textField.setText(Double.toString(result));
                } catch (Exception ex) {
                    textField.setText("Error");
                }
            } else if ("C".equals(buttonText)) {
                textField.setText("");
            } else {
                textField.setText(textField.getText() + buttonText);
            }
        }
    }

    private double evaluateExpression() throws Exception {
        String expression = textField.getText();
        if (!expression.contains(" ")) {
            stack.push(expression);
            return Double.parseDouble(expression);
        } else {
            String[] parts = expression.split(" ");
            String operator = parts[1];
            double firstNumber = Double.parseDouble(stack.pop());
            double secondNumber = Double.parseDouble(stack.pop());
            double result = 0;
            switch (operator) {
                case "+":
                    result = secondNumber + firstNumber;
                    break;
                case "-":
                    result = secondNumber - firstNumber;
                    break;
                case "*":
                    result = secondNumber * firstNumber;
                    break;
                case "/":
                    if (firstNumber != 0) {
                        result = secondNumber / firstNumber;
                    } else {
                        throw new ArithmeticException("Division by zero is not allowed.");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid operator");
            }
            stack.push(Double.toString(result));
            return result;
        }
    }
}
