function findMinimumIndex(nums) {
  let minimum = nums[0];
  let minimumIndex = 0;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] < minimum) {
      minimum = nums[i];
      minimumIndex = i;
    }
  }
  return minimumIndex;
}

/**
 * Sorts an array using the selection sort algorithm.
 * 
 * This function implements the selection sort algorithm, which repeatedly
 * finds the minimum element from the unsorted part of the array and moves it
 * to the beginning. It maintains two subarrays within the given array:
 * the subarray which is already sorted, and the remaining subarray which is unsorted.
 * In every iteration, the minimum element from the unsorted subarray is picked
 * and moved to the sorted subarray.
 * 
 * @param {number[]} nums - The array of numbers to be sorted.
 * @returns {number[]} A new array containing the sorted elements.
 */
function selectionSort(nums) {
  let sortedArray = [];
  while (nums.length > 0) {
    let minimumIndex = findMinimumIndex(nums);
    sortedArray.push(nums.splice(minimumIndex, 1)[0]);
  }
  return sortedArray;
}

