// Calculate the power of a number using a loop.
//
// This function takes two integers, base and exponent, and calculates the power
// of the base to the exponent. If the exponent is negative, it calculates the
// reciprocal of the power for positive exponent values. The result is rounded to 2 decimal places.
//
// Parameters:
// base (int): The base number to be raised to the power of exponent.
// exponent (int): The exponent indicating the power to raise the base to.
//
// Returns:
// float64: The result of raising base to the power of exponent, rounded to 2 decimal places.
func calculatePower(base int, exponent int) float64 {
	if exponent == 0 {
		return 1.0 // Any number to the power of 0 is 1
	}

	result := 1.0
	isNegativeExponent := exponent < 0
	exponent = int(math.Abs(float64(exponent)))

	for i := 0; i < exponent; i++ {
		result *= float64(base)
	}

	if isNegativeExponent {
		result = 1 / result
	}

	return math.Round(result*100) / 100
}

// check function to verify the correctness of the calculatePower function.
func check() {
	fmt.Printf("%.2f\n", calculatePower(2, 3))   // Output: 8.00
	fmt.Printf("%.2f\n", calculatePower(2, -3))  // Output: 0.13
	fmt.Printf("%.2f\n", calculatePower(5, 0))   // Output: 1.00
	fmt.Printf("%.2f\n", calculatePower(10, 1))  // Output: 10.00
}

func main() {
	check()
}

pe::Status
PeFileReader::ReadSectionHeader(const char *filename, uint32_t section_index,
                                SectionHeader *header)
{
    if (!header) {
        return pe::kErrNullPointer;
    }

    pe::Status status = ReadFile(filename);
    if (status != pe::kSuccess) {
        return status;
    }

    const uint8_t *data = reinterpret_cast<const uint8_t*>(file_data);
    if (data == nullptr) {
        return pe::kErrInternalError;
    }

    // Read the section header.
    const pe::PeFileHeader *header_info = reinterpret_cast<const pe::PeFileHeader*>(data);
    if (section_index >= header_info->NumberOfSections) {
        return pe::kErrOutOfRange;
    }

    const pe::PeSectionHeader *section_header =
        reinterpret_cast<const pe::PeSectionHeader*>(data + header_info->SizeOfOptionalHeader);
    *header = *section_header + section_index;

    return pe::kSuccess;
}

