    private function updateEntity($id, Request $request)
    {
        $entity = $this->repository->find($id);

        if (is_null($entity)) {
            return $this->responseNotFound();
        }

        $entity = $this->repository->update($entity, $request->all());

        if (is_null($entity)) {
            return $this->responseInternalServerError();
        }

        return $this->responseOk($entity);
    }

