     * @param mixed $id
     *
     * @return Response
     */
    private function deleteEntity($id)
    {
        $entity = $this->repository->find($id);

        if (is_null($entity)) {
            return $this->responseNotFound();
        }

        $this->repository->delete($entity);

        return $this->responseNoContent();
    }

