class Solution {
    // Finds the maximum sum of any contiguous subarray of size k.
    public static long FindMaxSumSubarray(int[] nums, int k) {
        if (nums == null || k <= 0 || k > nums.Length) {
            return 0;
        }

        long maxSum = 0, currentSum = 0;
        for (int i = 0; i < nums.Length; i++) {
            currentSum += nums[i];
            if (i >= k - 1) {
                maxSum = Math.Max(maxSum, currentSum);
                currentSum -= nums[i - k + 1];
            }
        }
        return maxSum;
    }

    // A check function to verify the correctness of the generated function with provided data points.
    public static void Check() {
        Console.WriteLine(FindMaxSumSubarray(new int[]{2, 1, 5, 1, 3, 2}, 3)); // Expected output: 9
        Console.WriteLine(FindMaxSumSubarray(new int[]{2, 3, 4, 1, 5}, 2)); // Expected output: 7
    }
}

class Program {
    static void Main(string[] args) {
        Solution.Check();
    }
}
```

