    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        System.out.println(findMaxProduct(nums)); // Output: 6
    }

    public static int findMaxProduct(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;

        int maxProduct = Integer.MIN_VALUE;
        int maxSoFar = 1;
        int minSoFar = 1;

        for (int num : nums) {
            if (num == 0) {
                maxSoFar = 1;
                minSoFar = 1;
                continue;
            }

            int tempMax = Math.max(num, Math.max(maxSoFar * num, minSoFar * num));
            minSoFar = Math.min(num, Math.min(maxSoFar * num, minSoFar * num));
            maxSoFar = tempMax;

            maxProduct = Math.max(maxProduct, maxSoFar);
        }

        return maxProduct;
    }
}

